/* ManifestMapper.selectMasterOdJobNoList : MASTER_OD_JOB_NO 조회 */
SELECT od.MASTER_OD_JOB_NO
FROM TB_ECM_OD od
	 INNER JOIN TB_ECM_OD_ADDITIONAL ad
	 			ON ad.OD_JOB_NO = od.OD_JOB_NO
WHERE od.ENT_CODE = #{srchEntCode}
AND od.BL_TYPE_MH = 'H'

	
		
		AND ${srchNoType} IN (#{item})
		
		
		AND ${srchNoType} = #{srchNo}
		
	

GROUP BY od.MASTER_OD_JOB_NO

