/* ManifestMapper.updateSimpleError : 통관목록 오류건 업데이트 */ UPDATE ad SET ad.SIMPLE_DOC_NO = CASE WHEN od.DOCUMENT_YN = 'Y' THEN #{simpleDocNoY} ELSE #{simpleDocNoN} END ,ad.SIMPLE_DOC_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE()) ,ad.SIMPLE_DOC_TIME = CONVERT(VARCHAR(5), DATEADD(HOUR, ${gmtTime}, GETDATE()), 108) ,ad.SIMPLE_ERROR_SEND_YN = 'Y' FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
AND od.MASTER_OD_JOB_NO = #{srchMasterOdJobNo}
AND (od.ECM_YN = #{srchEcmYn} OR od.ECM_YN IS NULL)
AND od.ECM_YN = #{srchEcmYn}

