/* ManifestMapper.selectDeleteMasterOrderCheck : 마스터오더삭제전체크 */ SELECT COUNT(od.OD_JOB_NO) AS CNT FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO AND ISNULL(ad.SIMPLE_EDI_STATUS, '') NOT IN ('', 'ERROR', 'RECV03')
WHERE od.OD_JOB_NO IN(#{item})
WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo}

