mapper.select:
/* ManifestMapper.selectCarryinInList : 적하목록/오더조회 - 지정창고 반출요청 List */

SELECT A.* 
FROM(
	SELECT 
		   ent.ENT_NAME
		 , od.AR_DATE
		 , od.ORIG_COUNTRY
		 , od.ORIG_NAME
		 , od.DEST_NAME
		 , con.CNTR_NO
		 , con.CBM
		 , od.PIECES
		 , od.GWT
		 , od.MBL_NO
		 , od.REMARKS
	FROM TB_ECM_OD od
		 INNER JOIN TB_ECM_OD_ADDITIONAL ad
		 			ON ad.OD_JOB_NO = od.OD_JOB_NO
	LEFT JOIN exps_master.dbo.TB_SMS_ENTERPRISE ent ON od.ENT_CODE = ent.ENT_CODE
	LEFT JOIN TB_ECM_OD_CONTAINER con ON od.OD_JOB_NO = con.OD_JOB_NO 
	WHERE 1=1
	AND od.ENT_CODE = #{srchEntCode}
	
	AND od.MASTER_OD_JOB_NO  = #{srchMasterOdJobNo}
		
		AND ad.SIMPLE_DOC_NO IS NULL
		
	
	
	AND od.MASTER_OD_JOB_NO IN ${srchMasterOdJobNoListStr}
	
	
	AND ad.SIMPLE_DOC_NO  = #{srchSimpleDocNo}
	
	
	
	AND od.SOLUTION = #{srchSolution}
	
	
	AND od.BL_TYPE_MH = #{srchBlTypeMh}
	
	
	AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) 
	AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
	
	
	AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'EXP'
	AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP'
	AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'EXP'
	AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'
	
	
	AND od.CONSOL_YN = #{srchConsolYn}
	
	
	AND ad.LAST_POD_STATUS = #{srchLastPodStatus}
	
	
	AND od.CARRYIN_DATE IS NOT NULL
	
	
	AND od.CARRYIN_DATE IS NULL
	
	
	AND od.CARRYOUT_DATE IS NOT NULL
	
	
	AND od.CARRYOUT_DATE IS NULL
	
	
	AND od.CD_TYPE = #{srchCdType}
	
	
	
	AND od.INSPECTION_YN = #{srchInspectionYn}
	
	
	AND ad.SE_INSPECTION_YN = #{srchSeInspectionYn}
	
	
	AND ad.XRAY_YN = #{srchXrayYn}
	
	
	AND ad.DROP_YN = #{srchDropYn}
	
	
	AND ad.SIMPLE_EDI_STATUS = #{srchSimpleEdiStatus}
	
	
	AND ad.SIMPLE_STATEMENT_YN = #{srchSimpleStatementYn}
	

	
	AND od.MULTI_YN = #{srchMultiYn}
	
	
	AND (SELECT COUNT(*) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N') > 0
	
	
	AND od.CUSTOMS_ID_VERIFY = 'TODO'
	
	
	AND od.SMS_INFORM_YN = #{srchSmsInformYn}
	
	
	
		
		
		AND ${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
		
		
		AND ${srchNoType} = #{srchNo}
		
		
	
	
	AND ${srchCusType} = #{srchCus}
		
) A

WHERE ABNORMAL_CODE IS NOT NULL

/* ManifestMapper.selectHouseOutList : 적하목록 House Out List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT * FROM ( SELECT od.OD_JOB_NO ,od.MASTER_OD_JOB_NO
,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'STATUS_ORDER_CARGO' AND CODE = odAdd.LAST_POD_STATUS) AS LAST_POD_STATUS
,odAdd.LAST_POD_STATUS
,ROW_NUMBER() OVER(PARTITION BY od.OD_JOB_NO ORDER BY od.OD_JOB_NO) AS H_NUM ,odAdd.SIMPLE_DOC_NO ,CASE WHEN od.CD_TYPE = 'Y' THEN odAdd.SIMPLE_REPORT_DATE END AS SIMPLE_REPORT_DATE ,CASE WHEN od.CD_TYPE = 'Y' THEN odAdd.SIMPLE_DOC_DATE END AS SIMPLE_DOC_DATE ,CASE WHEN od.CD_TYPE = 'Y' THEN odAdd.SIMPLE_RESPONSE_DATE END AS SIMPLE_RESPONSE_DATE ,odAdd.CLEARANCE_RECEIPT_DATE ,CASE WHEN od.CD_TYPE = 'E' THEN odAdd.SIMPLE_EDI_STATUS END AS SIMPLE_EDI_STATUS_LICENSE ,CASE WHEN od.CD_TYPE = 'E' THEN odAdd.SIMPLE_DOC_DATE END AS SIMPLE_DOC_DATE_LICENSE ,CASE WHEN od.CD_TYPE = 'E' THEN odAdd.SIMPLE_REPORT_DATE END AS SIMPLE_REPORT_DATE_LICENSE ,CASE WHEN od.CD_TYPE = 'E' THEN odAdd.SIMPLE_RESPONSE_DATE END AS SIMPLE_RESPONSE_DATE_LICENSE ,od.BOUND ,od.BOUND_TYPE ,od.HSN ,od.MBL_NO ,od.HBL_NO ,od.PO_DATE ,od.CD_TYPE ,od.CD_USE_TYPE ,od.ECM_TYPE ,od.INSPECTION_YN ,odAdd.SE_INSPECTION_YN ,odAdd.DROP_YN ,odAdd.XRAY_YN ,od.GE_INSPECTION_YN ,(SELECT TOP 1 MIN(HOLD_RELEASE_YN) OVER(PARTITION BY OD_JOB_NO) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO) AS HOLD_RELEASE_YN ,od.PIECES ,od.PIECES_REAL ,od.CURRENCY_CODE ,od.GWT ,od.AMOUNT_LOC ,od.AMOUNT_CUR ,od.DEST_PORT ,od.ALLOWED_ITEM_CODE ,od.COMMODITY_ITEM ,od.CONSIGNEE_NAME ,CONCAT(ISNULL(od.CONSIGNEE_ADDRESS, ''), ISNULL(od.CONSIGNEE_ADDRESS_A, ''), ISNULL(od.CONSIGNEE_ADDRESS_B, ''), ISNULL(od.CONSIGNEE_ADDRESS_C, ''), ISNULL(od.CONSIGNEE_ADDRESS_D, '')) AS CONSIGNEE_ADDRESS ,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_BUSINESS_ID, 1) AS CONSIGNEE_BUSINESS_ID ,od.CONSIGNEE_NAME_LOC ,od.CONSIGNEE_ADDRESS_LOC ,od.CONSIGNEE_ZIPCODE ,od.CUSTOMS_ID_TYPE ,odAdd.CUSTOMS_ID_VERIFY ,odAdd.CUSTOMS_ID_ERROR ,od.ORIG_NAME ,od.ORIG_COUNTRY ,od.SHIPPER_NAME ,CONCAT(ISNULL(od.SHIPPER_ADDRESS, ''), ISNULL(od.SHIPPER_ADDRESS_A, ''), ISNULL(od.SHIPPER_ADDRESS_B, ''), ISNULL(od.SHIPPER_ADDRESS_C, ''), ISNULL(od.SHIPPER_ADDRESS_D, '')) AS SHIPPER_ADDRESS ,od.SHIPPER_TEL ,dbo.Cryptography(od.OD_JOB_NO, od.SHIPPER_BUSINESS_ID, 1) AS SHIPPER_BUSINESS_ID ,od.URL ,odAdd.DROP_CODE ,odAdd.LOAD_CMPL_YN ,od.TR_NAME ,od.CB_NAME ,od.DELIVERY_NAME ,CASE WHEN odAdd.SIMPLE_RESPONSE_DATE IS NOT NULL AND SIMPLE_EDI_STATUS = '1' THEN '선별통보' WHEN odAdd.SIMPLE_RESPONSE_DATE IS NOT NULL AND SIMPLE_EDI_STATUS = '2' THEN '결과통보' END REV_RESULT ,SUM(licen.PIECES) OVER(PARTITION BY od.OD_JOB_NO) AS LICENSE_PIECES ,SUM(licen.GWT) OVER(PARTITION BY od.OD_JOB_NO) AS LICENSE_GWT ,CASE WHEN (SELECT TOP 1 REFERENCE_NO_ID FROM TB_COM_FILE_SHARE WHERE ENT_CODE = od.ENT_CODE AND FUNC_JOB_NO = od.OD_JOB_NO ) IS NULL THEN 'N' ELSE 'Y' END AS FILE_SHARE
,odAdd.INSPECTION_RESUT_CODE ,odAdd.SIMPLE_DECLARATION_STATUS ,ISNULL(odAdd.AMS_YN, 'N') AS AMS_YN
,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) AS CONSIGNEE_HP ,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) AS CONSIGNEE_TEL ,dbo.Cryptography(od.OD_JOB_NO, od.CUSTOMS_ID_ENC, 1) AS CUSTOMS_ID
,od.CONSIGNEE_HP ,od.CONSIGNEE_TEL ,od.CUSTOMS_ID
,odAdd.CUSTOMS_ID_START_DATE ,odAdd.CUSTOMS_ID_END_DATE FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO LEFT JOIN TB_ECM_OD_LICENSE licen ON od.OD_JOB_NO = licen.OD_JOB_NO LEFT JOIN TB_ECM_OD_ABNORMAL abnor ON od.OD_JOB_NO = abnor.OD_JOB_NO WHERE od.ENT_CODE = #{srchEntCode} AND od.BL_TYPE_MH = 'H'
AND od.MASTER_OD_JOB_NO = #{masterOdJobNo}
AND odAdd.SIMPLE_DOC_NO = #{simpleDocNo}
AND ISNULL(odAdd.SIMPLE_DOC_NO,'') = ''
AND od.CD_TYPE IN (#{item})
AND(
(odAdd.MF_DATE IS NULL AND od.CD_TYPE = 'N') (ISNULL(odAdd.SIMPLE_DOC_NO, '') = '' AND od.CD_TYPE = 'Y') (odAdd.SIMPLE_EDI_STATUS = 'RECV' AND od.CD_TYPE = 'Y') (odAdd.SIMPLE_EDI_STATUS = 'READY' AND od.CD_TYPE = 'Y') (odAdd.SIMPLE_EDI_STATUS = 'ERROR' AND od.CD_TYPE = 'Y') (ISNULL(odAdd.SIMPLE_DOC_NO, '') = '' AND od.CD_TYPE = 'E') (odAdd.SIMPLE_EDI_STATUS IN('RECV01', 'RECV02', 'RECV03') AND od.CD_TYPE = 'E') (odAdd.SIMPLE_EDI_STATUS IN('SEND01', 'SEND02', 'SEND03') AND od.CD_TYPE = 'E') (odAdd.SIMPLE_EDI_STATUS = 'ERROR' AND od.CD_TYPE = 'E') odAdd.SIMPLE_EDI_STATUS IN ('SEND01', 'SEND02', 'SEND03', 'READY') odAdd.SIMPLE_EDI_STATUS = 'ERROR'
)
AND odAdd.SIMPLE_DECLARATION_STATUS IN (#{item})
AND ${srchHNoType} IN (#{item})
AND ${srchHNoType} = #{srchHNo}
AND od.CD_TYPE = #{srchCdType}
AND od.INSPECTION_YN = #{srchInspectionYn}
AND odAdd.SE_INSPECTION_YN = #{srchSeInspectionYn}
AND odAdd.XRAY_YN = #{srchXrayYn}
AND odAdd.DROP_YN = #{srchDropYn}
AND odAdd.SIMPLE_EDI_STATUS = #{srchSimpleEdiStatus}
AND abnor.ABNORMAL_CODE IS NOT NULL
AND odAdd.SIMPLE_STATEMENT_YN = #{srchSimpleStatementYn}
AND od.MASTER_OD_JOB_NO IN ${srchMasterOdJobNoListStr}
) HINFO WHERE H_NUM = 1

mapper.insert:
/* ManifestMapper.insertBmsInPlan : BMS반입예정생성 */ DECLARE @IN_PLAN_NO TABLE (IN_PLAN_NO INT);
INSERT INTO TB_BMS_IN_PLAN( OD_JOB_NO ,CARGO_REFERENCE_NO ,BL_NO ,MBL_NO ,PKG_TYPE ,EX_CT ,EX_WT ,EX_CBM ,CUSTOMS_CODE ,CUSTOMS_DPT_CODE ,VESSEL_FLIGHT ,VOYAGE ,AR_DATE ,AR_TIME ,COMMODITY_ITEM_LOC ,SHIPPER_NAME ,SHIPPER_ADDRESS_1 ,SHIPPER_ADDRESS_2 ,CONSIGNEE_NAME ,CONSIGNEE_ADDRESS_1 ,CONSIGNEE_ADDRESS_2 ,CONSIGNEE_BUSINESS_ID ,CONSIGNEE_TEL
,CARRIER_CODE ,CNTR_NO ,ORIG_COUNTRY ,SE_INSPECTION_CODE ,SIMPLE_AUTH_NAME ,INSPECTION_TYPE
,CD_TYPE ,ECM_TYPE ,CD_USE_TYPE ,AMOUNT_USD ,REGISTER_USER_ID ,REGISTER_DATE_TIME ,UPDATE_USER_ID ,UPDATE_DATE_TIME ,DELIVERY_CODE ,DELIVERY_NAME ,SHIPPER_TEL ,CRIME_SELECTION_YN ,INSPECTION_CUSTOMS_YN ) OUTPUT INSERTED.IN_PLAN_NO INTO @IN_PLAN_NO (IN_PLAN_NO) VALUES ( #{OD_JOB_NO} ,CASE WHEN #{CARGO_REFERENCE_NO} IS NULL THEN '' ELSE #{CARGO_REFERENCE_NO} END ,CASE WHEN #{HBL_NO} IS NULL THEN '' ELSE #{HBL_NO} END ,CASE WHEN #{MBL_NO} IS NULL THEN '' ELSE #{MBL_NO} END ,CASE WHEN #{PKG_TYPE} IS NULL THEN '' ELSE #{PKG_TYPE} END ,CASE WHEN #{PIECES} IS NULL THEN 0 ELSE #{PIECES} END ,CASE WHEN #{GWT} IS NULL THEN 0 ELSE #{GWT} END ,CASE WHEN #{CBM} IS NULL THEN 0 ELSE #{CBM} END ,CASE WHEN #{bmsCustomsCode} IS NULL THEN '' ELSE #{bmsCustomsCode} END ,CASE WHEN #{bmsCustomsDptCode} IS NULL THEN '' ELSE #{bmsCustomsDptCode} END ,CASE WHEN #{VESSEL_FLIGHT} IS NULL THEN '' ELSE #{VESSEL_FLIGHT} END ,CASE WHEN #{VOYAGE} IS NULL THEN '' ELSE #{VOYAGE} END ,CASE WHEN #{AR_DATE_STR} IS NULL THEN '' ELSE #{AR_DATE_STR} END ,CASE WHEN #{AR_TIME} IS NULL THEN '' ELSE #{AR_TIME} END ,CASE WHEN #{COMMODITY_ITEM} IS NULL THEN N'' ELSE #{COMMODITY_ITEM} END ,CASE WHEN #{SHIPPER_NAME} IS NULL THEN N'' ELSE #{SHIPPER_NAME} END ,CASE WHEN #{SHIPPER_ADDRESS_1} IS NULL THEN N'' ELSE #{SHIPPER_ADDRESS_1} END ,CASE WHEN #{SHIPPER_ADDRESS_2} IS NULL THEN N'' ELSE #{SHIPPER_ADDRESS_2} END ,CASE WHEN #{CONSIGNEE_NAME} IS NULL THEN N'' ELSE #{CONSIGNEE_NAME} END ,CASE WHEN #{CONSIGNEE_ADDRESS_1} IS NULL THEN N'' ELSE #{CONSIGNEE_ADDRESS_1} END ,CASE WHEN #{CONSIGNEE_ADDRESS_2} IS NULL THEN N'' ELSE #{CONSIGNEE_ADDRESS_2} END ,CASE WHEN #{CONSIGNEE_BUSINESS_ID} IS NULL THEN '' ELSE #{CONSIGNEE_BUSINESS_ID} END ,CASE WHEN #{CONSIGNEE_TEL} IS NULL THEN '' ELSE #{CONSIGNEE_TEL} END
,CASE WHEN #{b2gForwarderSign} IS NULL THEN '' ELSE #{b2gForwarderSign} END ,CASE WHEN #{CNTR_NO} IS NULL THEN '' ELSE #{CNTR_NO} END ,CASE WHEN #{ORIG_COUNTRY} IS NULL THEN '' ELSE #{ORIG_COUNTRY} END ,CASE WHEN #{SE_INSPECTION_CODE} IS NULL THEN '' ELSE #{SE_INSPECTION_CODE} END ,CASE WHEN #{SIMPLE_AUTH_NAME} IS NULL THEN N'' ELSE #{SIMPLE_AUTH_NAME} END ,CASE WHEN #{INSPECTION_TYPE} IS NULL THEN '' ELSE #{INSPECTION_TYPE} END
,CASE WHEN #{CD_TYPE} IS NULL THEN '' ELSE #{CD_TYPE} END ,CASE WHEN #{ECM_TYPE} IS NULL THEN '' ELSE #{ECM_TYPE} END ,CASE WHEN #{CD_USE_TYPE} IS NULL THEN '' ELSE #{CD_USE_TYPE} END ,CASE WHEN #{AMOUNT_USD} IS NULL THEN 0 ELSE #{AMOUNT_USD} END ,'DAEMON' ,GETDATE() ,'DAEMON' ,GETDATE() ,CASE WHEN #{DELIVERY_CODE} IS NULL THEN '' ELSE #{DELIVERY_CODE} END ,CASE WHEN #{DELIVERY_NAME} IS NULL THEN '' ELSE #{DELIVERY_NAME} END ,CASE WHEN #{SHIPPER_TEL} IS NULL THEN '' ELSE #{SHIPPER_TEL} END ,CASE WHEN #{CRIME_SELECTION_YN} IS NULL THEN '' ELSE #{CRIME_SELECTION_YN} END ,CASE WHEN #{CRIME_SELECTION_YN} IS NULL THEN '' ELSE #{CRIME_SELECTION_YN} END );
INSERT INTO TB_BMS_IN_PLAN_CONTAINER( IN_PLAN_NO ,CNTR_NO ,CNTR_EDI_CODE ,SEAL_NO_1 ,SEAL_NO_2 ,SEAL_NO_3 ) SELECT (SELECT TOP 1 IN_PLAN_NO FROM @IN_PLAN_NO) ,ISNULL(CNTR_NO, '') ,ISNULL(CNTR_EDI_CODE, '') ,ISNULL(CNTR_SEAL_NO_1, '') ,ISNULL(CNTR_SEAL_NO_2, '') ,ISNULL(CNTR_SEAL_NO_3, '') FROM TB_ECM_OD_CONTAINER WHERE OD_JOB_NO = #{OD_JOB_NO};
INSERT INTO TB_BMS_IN_PLAN_PKG( IN_PLAN_NO ,BL_NO ,PACKING_NO ) SELECT (SELECT TOP 1 IN_PLAN_NO FROM @IN_PLAN_NO) ,CASE WHEN ISNULL(DELIVERY_NO, '') = '' THEN #{HBL_NO} ELSE DELIVERY_NO END ,ISNULL(PACKING_NO, '') FROM TB_ECM_OD_PACKING WHERE OD_JOB_NO = #{OD_JOB_NO};
INSERT INTO TB_BMS_XRAY_RESULT( IN_PLAN_NO , CARGO_REFERENCE_NO ) SELECT IN_PLAN_NO , CASE WHEN #{CARGO_REFERENCE_NO} IS NULL THEN '' ELSE #{CARGO_REFERENCE_NO} END FROM @IN_PLAN_NO;
UPDATE TB_ECM_OD_ADDITIONAL SET CFA_DATE = GETDATE() WHERE OD_JOB_NO = #{OD_JOB_NO};
INSERT INTO TB_ECM_POD_05 ( ENT_CODE ,OD_JOB_NO ,POD_STATUS ,POD_NAME ,POD_DATE ,POD_TIME ,REMARKS ,REGISTER_USER_ID ,REGISTER_DATE_TIME ,UPDATE_USER_ID ,UPDATE_DATE_TIME )VALUES( #{entCode} ,#{OD_JOB_NO} ,'ECM288' ,'반입예정생성' ,DATEADD(HOUR, ${gmtTime}, GETDATE()) ,SUBSTRING(CONVERT(VARCHAR(10), DATEADD(HOUR, ${gmtTime}, GETDATE()), 108), 1, 8) ,'수동생성' ,#{userId} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) ,#{userId} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) );

mapper.delete:
		/* ManifestMapper.deleteBmsInPlan : BMS반입예정삭제 */
		DELETE FROM TB_BMS_IN_PLAN WHERE IN_PLAN_NO = #{inPlanNo};
		DELETE FROM TB_BMS_IN_PLAN_CONTAINER WHERE IN_PLAN_NO = #{inPlanNo};
		DELETE FROM TB_BMS_IN_PLAN_PKG WHERE IN_PLAN_NO = #{inPlanNo};
		DELETE FROM TB_BMS_XRAY_RESULT WHERE IN_PLAN_NO = #{inPlanNo};
		UPDATE TB_ECM_OD_ADDITIONAL SET CFA_DATE = NULL WHERE OD_JOB_NO = #{odJobNo};
		INSERT INTO TB_ECM_POD_05 (
			   ENT_CODE
			  ,OD_JOB_NO
			  ,POD_STATUS
			  ,POD_NAME
			  ,POD_DATE
			  ,POD_TIME
			  ,REMARKS
			  ,REGISTER_USER_ID
			  ,REGISTER_DATE_TIME
			  ,UPDATE_USER_ID
			  ,UPDATE_DATE_TIME
        )VALUES(
               #{entCode}
			  ,#{odJobNo}
			  ,'ECM288'
			  ,'반입예정삭제'
			  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
			  ,SUBSTRING(CONVERT(VARCHAR(10), DATEADD(HOUR, ${gmtTime}, GETDATE()), 108), 1, 8)
			  ,'수동삭제'
			  ,#{userId}
			  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
			  ,#{userId}
			  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
        );

mapper.select:
/* ManifestMapper.customsManifestResList : 통관목록결과조회 */
SELECT od.MRN AS mrn ,od.MSN AS msn ,od.HSN AS hsn ,od.HBL_NO AS hblNo ,od.OD_JOB_NO ,od.BOUND ,od.BOUND_TYPE ,ad.SIMPLE_DOC_NO AS simpleDocNo ,ad.SIMPLE_ERROR_DESC AS simpleErrorDesc ,ad.CLEARANCE_YN AS clearanceYn ,CASE WHEN ad.SIMPLE_RESPONSE_DATE IS NOT NULL THEN ad.SIMPLE_RESPONSE_DATE ELSE ad.SIMPLE_RESULT_DATE END AS resDateTime ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND CODE = od.CUSTOMS_CODE AND GROUP_CODE = 'EDI_CUSTOMS_CODE') AS customsName ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND CODE = od.CUSTOMS_DPT_CODE AND GROUP_CODE = 'EDI_CUSTOMS_DEPT_CODE') AS customsDptName ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND CODE = ad.SE_INSPECTION_CODE AND GROUP_CODE = 'SE_INSPECTION_CODE') AS seInspectionCodeName ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND CODE = ad.DROP_CODE AND GROUP_CODE = 'DROP_CODE') AS dropCodeName ,(SELECT NAME_${userLanguage} FROM exps_master.dbo.TB_SMS_MESSAGE WHERE MESSAGE_ID = CASE ad.SIMPLE_EDI_STATUS WHEN 'ERROR' THEN 'EXPS003666' WHEN 'RECV' THEN 'EXPS003667' WHEN '1' THEN 'EXPS002842' WHEN '2' THEN 'EXPS002842' END) AS simpleEdiStatus FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO WHERE od.MASTER_OD_JOB_NO = #{odJobNo}
AND ad.SIMPLE_DOC_NO = #{simpleDocNo}
AND (ISNULL(ad.SIMPLE_ERROR_DESC, '') != '' OR ad.DROP_YN = 'Y' OR ad.SE_INSPECTION_YN = 'Y')

mapper.update:
/* ManifestMapper.updateCarryinNo : 반입근거번호 업데이트 */
	UPDATE TB_ECM_OD SET
		   CARRYIN_NO = #{carryinNo}
	WHERE MASTER_OD_JOB_NO = #{odJobNo}
	AND BL_TYPE_MH = 'H'

/* ManifestMapper.updateBusinessFinish : 업무마감 */
	UPDATE TB_ECM_OD_ADDITIONAL SET
		   BUSINESS_FINISH_YN = CASE WHEN BUSINESS_FINISH_YN = 'Y' THEN '' ELSE 'Y' END
		  ,BUSINESS_FINISH_USER_ID = CASE WHEN BUSINESS_FINISH_YN = 'Y' THEN '' ELSE #{registerUserId} END
		  ,BUSINESS_FINISH_DATE_TIME = CASE WHEN BUSINESS_FINISH_YN = 'Y' THEN '' ELSE DATEADD(HOUR, ${gmtTime}, GETDATE()) END
	WHERE BL_TYPE_MH = 'H'
	AND (
	
	(
		MASTER_OD_JOB_NO = #{item.odJobNo}
		
		
		AND SIMPLE_DOC_NO = #{item.simpleDocNo}
		
		
		AND ISNULL(SIMPLE_DOC_NO, '') = ''
		
		
	)
	
	)

		/* ManifestMapper.updateOrder : Order updateOrder */
		
						
			UPDATE TB_ECM_OD SET
				 MRN = #{mrn}
				,MSN = #{msn}
				,MBL_NO = #{mblNo}
				,VESSEL_FLIGHT = #{vesselFlight}
				,LINE_CODE = #{lineCode}
				,ORIG_CODE = #{origCode}
				,ORIG_NAME = #{origName}



				,OB_DATE = #{obDate}
				,OB_TIME = #{obTime}
				,AR_DATE = #{arDate}
				,AR_TIME = #{arTime}
				
				
				,PIECES = #{pieces}
				,GWT = #{gwt}
				,ASSIGNMENT_WH_CODE = #{assignmentWhCode}
				,REMARKS = #{remarks}
				
				
					
					,ASSIGNMENT_WH_CODE = #{assignmentWhCode}
					
					
					,CARRYIN_NO = #{carryinNo}
					
				
				


				
				,DISC_WH_CODE = #{discWhCode}






				,AMOUNT_LOC = ISNULL(#{amountLoc}, 0)
				,AMOUNT_USD = ISNULL(#{amountUsd}, 0)
				,EXCHANGE_RATE = ISNULL(#{exchangeRate}, 0)
				,VENDER_ID_1 = #{venderId1}
				
				,ORIG_COUNTRY = #{origCountry}
				

				,SHIPPER_COUNTRY_CODE = #{origCountry}

				,TR_CODE = #{trCode}
				,ASSIGNMENT_CODE = #{assignmentCode}
				
				
				,DEST_CODE = #{destCode}
				,DEST_NAME = #{destName}
				,DEST_PORT = #{destPort}
				,CUSTOMS_CODE = #{customsCode}
				,CUSTOMS_DPT_CODE = #{customsDptCode}
				,DEST_COUNTRY = #{destCountry}
