/* ManifestMapper.updateComObl : 적하목록 수정시 TB_COM_OBL 수정 */
	UPDATE TB_COM_OBL SET
		   MBL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))
		  ,ORIG_CODE = #{origCode}
		  ,ORIG_NAME = #{origName}
		  
		  ,DEST_CODE = #{destCode}
		  ,DEST_NAME = #{destName}
		  
		  ,OB_DATE = CONVERT(DATE, #{obDate},  ${dateFormat})
		  ,OB_TIME = #{obTime}
		  ,AR_DATE = CONVERT(DATE, #{arDate},  ${dateFormat})
		  ,AR_TIME = #{arTime}
		  ,PIECES = #{pieces}
		  ,GWT = #{gwt}
		  ,ISSUE_DATE = CONVERT(DATE, #{obDate},  ${dateFormat})
		  
		  
		  ,VESSEL_FLIGHT = #{vesselFlight}
		  ,VESSEL_VOYAGE = #{vesselVoyage}
		  ,VESSEL_SIGN = #{vesselSign}
		  
		  
		  ,VIA_BY_A = #{vesselFlight}
		  ,VESSEL_FLIGHT = #{vesselFlight}
			  
			  ,ISSUE_PLACE_CODE = #{origCode}
			  
		  
		  
		  ,UPDATE_USER_ID = #{updateUserId}
		  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
	WHERE OBL_JOB_NO = #{oblJobNo}

/* ManifestMapper.updateComOrder : 적하목록 수정시 TB_COM_OD 수정 */
	UPDATE TB_COM_OD SET
		   MBL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))
		  
		  
		  ,OBAR_DATE = CONVERT(DATE, #{obDate},  ${dateFormat})
		  ,ORIG_DEST_CODE = #{destCode}
		  
		  
		  ,OBAR_DATE = CONVERT(DATE, #{arDate},  ${dateFormat})
		  ,ORIG_DEST_CODE = #{origCode}
		  
		  
		  ,UPDATE_USER_ID = #{updateUserId}
		  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
	WHERE OD_JOB_NO = #{odJobNo}

/* ManifestMapper.updateComOrderBus : 적하목록 수정시 TB_COM_OD_BUS 수정 */
	UPDATE TB_COM_OD_BUS SET
		   MBL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))
		  
		  
		  ,PORT_CODE = #{destCode}
		  
		  
		  ,PORT_CODE = #{origCode}
		  
		  
	WHERE OD_JOB_NO = #{odJobNo}

/* ManifestMapper.updateSimpleDocNo : 통관목록제출번호 업데이트 */
	UPDATE ad SET
		   ad.SIMPLE_DOC_NO = #{simpleDocNo}
	FROM TB_ECM_OD od
		 INNER JOIN TB_ECM_OD_ADDITIONAL ad
		 			ON ad.OD_JOB_NO = od.OD_JOB_NO
	WHERE od.MASTER_OD_JOB_NO = #{odJobNo}
	
	
	AND ad.SIMPLE_DOC_NO = #{oldSimpleDocNo}
	
	
	AND ad.SIMPLE_DOC_NO IS NULL
	AND (
		CASE WHEN od.DOCUMENT_YN = 'Y' THEN 'Y' ELSE 'N' END = #{documentYn}
		
		
		OR od.BL_TYPE_MH = 'M'
		
		
		AND od.BL_TYPE_MH = 'H'
		
		
	)

/* ManifestMapper.updateMrnResultType : MRN/MSN조회데몬 실행여부 업데이트 */
	UPDATE TB_ECM_OD SET
		   MRN_RESULT_TYPE = 'S'
	WHERE OD_JOB_NO = #{OD_JOB_NO}
	AND ISNULL(MRN_RESULT_TYPE, '') != 'E'

