/* ManifestMapper.selectResetSimpleDocNoList : 제출번호초기화대상 조회 */ SELECT od.OD_JOB_NO ,od.BOUND ,od.BOUND_TYPE ,od.ORIG_CODE ,od.DOCUMENT_YN ,od.CD_TYPE ,od.ENT_CODE ,od.ENT_BUSINESS_CODE FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO AND ISNULL(ad.SIMPLE_EDI_STATUS, '') IN('', 'ERROR', 'RECV03')
WHERE od.OD_JOB_NO IN(#{item})
WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo}
AND od.CD_TYPE = 'Y'
AND od.CD_TYPE = 'E'

/* ManifestMapper.getSeparationInfo : 개인통관오류건 조회 */ SELECT COUNT(CASE WHEN od.DOCUMENT_YN = 'Y' THEN ad.OD_JOB_NO END) AS DOCUMENT_Y_CNT ,COUNT(CASE WHEN od.DOCUMENT_YN != 'Y' THEN ad.OD_JOB_NO END) AS DOCUMENT_N_CNT ,COUNT(CASE WHEN od.DOCUMENT_YN = 'Y' THEN err.OD_JOB_NO END) AS DOCUMENT_Y_ERROR_CNT ,COUNT(CASE WHEN od.DOCUMENT_YN != 'Y' THEN err.OD_JOB_NO END) AS DOCUMENT_N_ERROR_CNT ,MAX(mad.SIMPLE_DOC_NO) AS SIMPLE_DOC_NO FROM TB_ECM_OD mod INNER JOIN TB_ECM_OD_ADDITIONAL mad ON mad.OD_JOB_NO = mod.OD_JOB_NO INNER JOIN TB_ECM_OD od ON od.MASTER_OD_JOB_NO = mod.OD_JOB_NO AND od.BL_TYPE_MH = 'H' AND od.CD_TYPE = 'Y' INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
AND ad.SIMPLE_DOC_NO = #{simpleDocNo}
AND ad.SIMPLE_DOC_NO IS NULL
LEFT JOIN TB_ECM_OD_ADDITIONAL err ON err.OD_JOB_NO = od.OD_JOB_NO AND ((err.SIMPLE_EDI_STATUS = 'ERROR' AND ISNULL(ad.SIMPLE_ERROR_DESC, '') != '') OR ad.CUSTOMS_ID_VERIFY IN('N', 'E')) WHERE mod.OD_JOB_NO = #{masterOdJobNo} AND mod.BL_TYPE_MH = 'M'

mapper.update:
/* ManifestMapper.updateOdForEdiStatus : EDI 문서(적하목록) 전송후 오더 테이블 상태값 변경 */
UPDATE TB_ECM_OD_ADDITIONAL SET LAST_POD_STATUS = CASE WHEN ISNULL(LAST_POD_STATUS, '') < #{lastPodStatus} THEN #{lastPodStatus} ELSE LAST_POD_STATUS END
,MF_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE()) ,MF_USER_ID = #{registerUserId} WHERE OD_JOB_NO IN(#{item}, #{odJobNo})
UPDATE ad SET ad.LAST_POD_STATUS = CASE WHEN ISNULL(ad.LAST_POD_STATUS, '') < #{lastPodStatus} THEN #{lastPodStatus} ELSE ad.LAST_POD_STATUS END
,ad.MF_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE()) ,ad.MF_USER_ID = #{registerUserId} FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO WHERE od.MASTER_OD_JOB_NO = #{odJobNo}
AND (od.CD_TYPE = #{cdType} OR od.BL_TYPE_MH = 'M')

