/* ManifestMapper.getEdiInterfaceInfo : 중개사업자별 문서 및 송/수신 정보 조회 */ SELECT TOP 1 interface.ENT_CODE ,interface.ENT_BUSINESS_CODE ,interface.IF_SERVICE_CODE ,interface.IF_DOC_CODE ,interface.USE_YN ,interface.IF_VENDER ,interface.IF_VENDER_SYSTEM ,interface.IF_SENDER_ID ,interface.IF_PIMA_CODE ,interface.IF_SVR_ID ,interface.IF_SVR_PW ,interface.IF_SVR_ROOT ,interface.IF_SVR_ROOT_SEND ,interface.IF_SVR_ROOT_RECV ,interface.IF_WEB_ID ,interface.IF_WEB_PWD ,interface.IF_ETC_1 ,interface.IF_ETC_2 ,interface.IF_ETC_3 ,interface.IF_ETC_4 ,interface.IF_ETC_5 ,interface.IF_ETC_6 ,interface.IF_ETC_7 ,interface.IF_ETC_8 ,interface.IF_ETC_9 ,interface.IF_ETC_10 ,interface.SOLUTION ,interface.BOUND ,interface.BOUND_TYPE ,interface.REMARKS ,det.ETC4 AS IF_S_R_TYPE ,det.ETC11 AS IF_RECEIVER_ID ,det.ETC9 AS IF_SVR_IP ,det.ETC10 AS IF_SVR_IP_PORT ,det.ETC12 AS IF_SVR_IP_PASSIVE_YN FROM TB_SMS_ENT_BUSINESS_INTERFACE interface INNER JOIN TB_SMS_CODE_DETAIL det ON det.ENT_CODE = interface.ENT_CODE AND det.GROUP_CODE = 'EDI_SERVICE_CODE' AND det.CODE = interface.IF_SERVICE_CODE WHERE interface.ENT_CODE = #{entCode} AND interface.ENT_BUSINESS_CODE = #{entBusinessCode}
AND interface.IF_SERVICE_CODE IN #{item}
AND interface.IF_SERVICE_CODE = #{ifServiceCode}
AND interface.USE_YN = #{srchEdiInterfaceUseYn}

/* ManifestMapper.ediManifestCustomsLicenseList : 적하목록 전송 오류검증 및 파일생성 면장정보 리스트 가져오기 */ SELECT lic.LICENSE_NO ,lic.PIECES ,lic.UNIT_PIECES ,lic.GWT ,lic.COMBINE_TYPE_A_Z ,lic.COMBINE_PIECES ,lic.UNIT_PIECES AS COMBINE_UNIT_PIECES ,lic.PARTIAL_YN ,lic.PARTIAL_SEQ ,(SELECT ETC1 FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{entCode} AND GROUP_CODE = 'UNIT_PIECES' AND CODE = lic.UNIT_PIECES) AS UNIT_PIECES_EDI FROM TB_ECM_OD_LICENSE lic WHERE lic.OD_JOB_NO = #{odJobNo}
AND lic.COMBINE_TYPE_A_Z = #{combineTypeAZ}
ORDER BY lic.LICENSE_NO

/* ManifestMapper.selectEmsInfo : EMS환적 전송정보조회 */
	SELECT
		 EMS_CUS_NO_AIR_IPO
		,EMS_CUS_NO_SEA
		,EMS_CUS_NO_SEA_IPO
		,EMS_CUS_NO_SEA_ALIBABA
	FROM TB_SMS_ENT_BUS_FMS
	WHERE ENT_CODE = #{entCode}
	AND ENT_BUSINESS_CODE = #{entBusinessCode}
	AND SOLUTION = 'FMS'

