/* ManifestMapper.updateAmsAddress : AMS주소 업데이트 */
	UPDATE TB_ECM_OD SET
		   SHIPPER_TEL = #{SHIPPER_TEL}
		  ,SHIPPER_STREET = #{SHIPPER_STREET}
		  ,SHIPPER_PLACE = #{SHIPPER_PLACE}
		  ,SHIPPER_STATE_CODE = #{SHIPPER_STATE_CODE}
		  ,SHIPPER_COUNTRY_CODE = #{SHIPPER_COUNTRY_CODE}
		  ,SHIPPER_ZIPCODE = #{SHIPPER_ZIPCODE}
		  ,CONSIGNEE_STREET = #{CONSIGNEE_STREET}
		  ,CONSIGNEE_PLACE = #{CONSIGNEE_PLACE}
		  ,CONSIGNEE_STATE_CODE = #{CONSIGNEE_STATE_CODE}
		  ,CONSIGNEE_COUNTRY_CODE = #{CONSIGNEE_COUNTRY_CODE}
		  ,CONSIGNEE_ZIPCODE = #{CONSIGNEE_ZIPCODE}
		  
		  
		  ,CONSIGNEE_TEL_ENC = dbo.Cryptography(#{OD_JOB_NO}, #{CONSIGNEE_TEL}, 0)
		  
		  
		  ,CONSIGNEE_TEL = #{CONSIGNEE_TEL}
		  
		  
	WHERE OD_JOB_NO = #{OD_JOB_NO}

mapper.select:
/* ManifestMapper.ediManifestContainerList : 적하목록 전송 오류검증 및 파일생성 컨테이너 리스트 가져오기 */
SELECT cntr.CNTR_NO ,cntr.CNTR_MOD_TYPE AS MOD_TYPE_CNTR ,MAX(cntr.BEFORE_VALUE) AS BEFORE_VALUE ,MAX(cntr.AFTER_VALUE) AS AFTER_VALUE ,MAX(cntr.CNTR_MOD_CODE) AS CNTR_MOD_CODE ,MAX(cntr.MOD_JOB_NO) AS MOD_JOB_NO ,MAX(cntr.CNTR_EDI_CODE) AS CNTR_EDI_CODE ,MAX(cntr.CNTR_SEAL_NO_1) AS CNTR_SEAL_NO_1 ,MAX(cntr.CNTR_SEAL_NO_2) AS CNTR_SEAL_NO_2 ,MAX(cntr.CNTR_SEAL_NO_3) AS CNTR_SEAL_NO_3 ,MAX(cntr.PIECES) AS PIECES ,MAX(cntr.UNIT_PIECES) AS UNIT_PIECES ,MAX(hbl.OD_JOB_NO) AS OD_JOB_NO ,MAX(hbl.MOD_REASON) AS MOD_REASON_NAME ,MAX(hbl.SEQ_NO_ID) AS SEQ_NO_ID FROM TB_EDI_MOD_HBL hbl INNER JOIN TB_EDI_MOD_CONTAINER cntr ON cntr.MOD_JOB_NO = hbl.MOD_JOB_NO AND cntr.SEQ_NO_ID = hbl.SEQ_NO_ID WHERE hbl.OD_JOB_NO = #{odJobNo} and hbl.MOD_JOB_NO = #{modJobNo} GROUP BY cntr.CNTR_NO, cntr.CNTR_MOD_TYPE
SELECT cntr.CNTR_NO ,cntr.PIECES ,cntr.UNIT_PIECES ,cntr.CNTR_SEAL_NO_1 ,cntr.CNTR_SEAL_NO_2 ,cntr.CNTR_SEAL_NO_3 ,cntr.CNTR_EDI_CODE ,(SELECT ETC1 FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{entCode} AND GROUP_CODE = 'UNIT_PIECES' AND CODE = cntr.UNIT_PIECES) AS UNIT_PIECES_EDI ,'I' AS MOD_TYPE_CNTR FROM TB_ECM_OD_CONTAINER cntr WHERE cntr.OD_JOB_NO = #{odJobNo}

/* ManifestMapper.getEdiMfModifyHblCtnrReasonList : 컨테이너정정학목조회 */
	SELECT
		 cntr.CNTR_MOD_CODE AS MOD_ITEM_CODE_CNTR
		,cntr.BEFORE_VALUE AS MOD_DESC_BEFORE
		,cntr.AFTER_VALUE AS MOD_DESC_AFTER
		,cntr.MOD_JOB_NO
		,(SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{entCode} AND GROUP_CODE = 'CNTR_MOD_CODE' AND CODE = cntr.CNTR_MOD_CODE) AS MOD_ITEM_NAME_CNTR
	FROM TB_EDI_MOD_CONTAINER cntr
	WHERE cntr.MOD_JOB_NO = #{modJobNo}
	AND cntr.SEQ_NO_ID = #{seqNoId}
	AND cntr.CNTR_NO = #{cntrNo}
	AND cntr.CNTR_MOD_TYPE = 'U'

/* ManifestMapper.selectLastMblInfo : 정정신고 마스터 조회 */
	SELECT TOP 1
		 mbl.MOD_JOB_NO
		,mbl.MOD_REQ_NO
		,mbl.MOD_SERIAL_NO
		,mblType.SEND_STATUS
		,mblType.MOD_JOB_NO AS MOD_JOB_NO_TYPE
		,mblType.MOD_REQ_DATE AS MOD_REQ_DATE_TYPE
		,mblType.MOD_SERIAL_NO AS MOD_SERIAL_NO_TYPE
		,mblType.HBL_CNT AS HBL_CNT_TYPE
		,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = mbl.ENT_CODE AND USER_ID = mblType.REGISTER_USER_ID) AS REGISTER_USER_NAME_TYPE
	FROM TB_EDI_MOD_MBL mbl
		 LEFT JOIN TB_EDI_MOD_MBL mblType
		 		   ON mblType.ENT_CODE = mbl.ENT_CODE
		 		   AND mblType.MBL_NO = mbl.MBL_NO
		 		   AND mblType.MOD_TYPE = #{modType}
		 		   AND ISNULL(mblType.SEND_STATUS, 'N') = 'N'
		 		   AND mblType.MBL_NO = #{mblNo}
		 		   
		 		   AND mblType.MOD_JOB_NO = #{modJobNo}
		 		   
	WHERE mbl.ENT_CODE = #{entCode}
	AND mbl.MRN = #{mrn}
	
	
	
	AND mbl.SOLUTION = #{solution}
	
	ORDER BY mbl.MOD_SERIAL_NO DESC

/* ManifestMapper.selectModMblInfo : 정정신고 마스터 조회 */ SELECT mbl.MOD_JOB_NO ,mbl.MOD_REQ_NO ,mbl.MOD_SERIAL_NO ,mbl.SEND_STATUS ,mbl.RECV_STATUS ,mbl.RESULT_STATUS ,mbl.MRN
,(SELECT COUNT(*) FROM TB_ECM_OD_CONTAINER WHERE OD_JOB_NO = #{odJobNo} AND CNTR_NO = #{cntrNo} AND CNTR_NO != #{origCntrNo}) AS CNTR_NO_CNT
,(SELECT COUNT(*) FROM TB_EDI_MOD_CONTAINER WHERE MOD_JOB_NO = mbl.MOD_JOB_NO AND SEQ_NO_ID = #{seqNoId} AND CNTR_SEQ_NO_ID != #{cntrSeqNoId} AND CNTR_MOD_CODE = #{cntrModCode}) AS CNTR_MOD_CODE_CNT
FROM TB_EDI_MOD_MBL mbl WHERE mbl.MOD_JOB_NO = #{modJobNo}

/* ManifestMapper.getEdiMfModifyMblModDeclareNoList : 정정신고 M.B/L MOD_DECLARE_NO 조회 */
	SELECT mbl.MOD_JOB_NO
	FROM TB_EDI_MOD_MBL mbl
	WHERE mbl.MOD_JOB_NO = #{modJobNo}
	AND mbl.SEND_DATE_TIME IS NOT NULL
	AND mbl.SEND_STATUS != 'E'

