/* ManifestMapper.updateCustomsManifest : 목록신고상태 */ UPDATE ad SET
ad.SIMPLE_EDI_STATUS = 'ERROR'
ad.SIMPLE_EDI_STATUS = 'READY'
,ad.LAST_POD_STATUS = CASE WHEN ISNULL(ad.LAST_POD_STATUS, '') = 'ECM111' THEN #{podStatus} ELSE CASE WHEN ISNULL(ad.LAST_POD_STATUS, '') < #{podStatus} THEN #{podStatus} ELSE ad.LAST_POD_STATUS END END ,ad.SIMPLE_ERROR_SEND_YN = 'N'
,ad.SIMPLE_DOC_DATE = #{simpleDocDate} ,ad.SIMPLE_DOC_TIME = CONVERT(VARCHAR(5), DATEADD(HOUR, ${gmtTime}, GETDATE()), 108) FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo}
WHERE od.OD_JOB_NO IN(#{item})
AND od.BL_TYPE_MH = 'H' AND od.BL_TYPE_IERT NOT IN('T', 'R') AND od.CD_TYPE = 'Y'
AND ad.SIMPLE_EDI_STATUS = 'READY'
AND (ad.SIMPLE_EDI_STATUS IS NULL OR ad.SIMPLE_EDI_STATUS = 'ERROR')
AND ad.SIMPLE_DOC_NO = #{simpleDocNo}
AND od.ORIG_CODE = #{origCode}
AND ad.SIMPLE_DOC_NO != '' AND ad.SIMPLE_DOC_NO IS NOT NULL

