		 			ON ad.OD_JOB_NO = od.OD_JOB_NO
	
	
	WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo}
	
	
	WHERE od.OD_JOB_NO IN(#{item})
	
	
	AND od.BL_TYPE_MH = 'H'
	
	
	AND ad.SIMPLE_DOC_NO = #{simpleDocNo}
	
	
	AND od.ORIG_CODE = #{origCode}
	
	
	AND ad.SIMPLE_DOC_NO != ''
	AND ad.SIMPLE_DOC_NO IS NOT NULL

