/* ManifestMapper.selectResetSendCustomsManifest : 목록신고초기화 데이터 조회 */ SELECT od.OD_JOB_NO ,od.BL_TYPE_MH FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo}
AND ad.SIMPLE_DOC_NO IN (#{item})
WHERE od.OD_JOB_NO IN(#{item})
AND od.BL_TYPE_MH = 'H'
AND od.BL_TYPE_IERT NOT IN('T', 'R') AND od.CD_TYPE = 'Y'
AND od.CD_TYPE = 'E'
UNION ALL SELECT od.OD_JOB_NO ,od.BL_TYPE_MH FROM TB_ECM_OD od WHERE od.OD_JOB_NO = #{masterOdJobNo}

/* ManifestMapper.selectCorrectMasterList : 적하정정 Master List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT mbl.MOD_JOB_NO ,mbl.ENT_CODE ,mbl.ENT_BUSINESS_CODE ,mbl.MRN ,mbl.MSN ,mbl.MBL_NO ,mbl.HBL_CNT ,mbl.MOD_SERIAL_NO ,mbl.MOD_REQ_DATE ,mbl.MOD_REQ_NO ,mbl.CUSTOMS_CODE ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = mbl.ENT_CODE AND CODE = mbl.CUSTOMS_CODE AND GROUP_CODE = 'EDI_CUSTOMS_CODE') AS CUSTOMS_NAME ,mbl.CUSTOMS_DPT_CODE ,mbl.SEND_STATUS ,mbl.SEND_DATE_TIME
,CASE WHEN ISNULL(mbl.RESULT_STATUS, '') != '' THEN mbl.RESULT_STATUS ELSE mbl.RECV_STATUS END AS RECV_STATUS ,CASE CASE WHEN ISNULL(mbl.RESULT_STATUS, '') != '' THEN mbl.RESULT_STATUS ELSE mbl.RECV_STATUS END WHEN 'A' THEN '접수' WHEN 'E' THEN '오류' WHEN '1' THEN '승인' WHEN '2' THEN '부분승인' WHEN '3' THEN '기각' WHEN '4' THEN '서류제출통보' END AS RECV_STATUS_NAME ,mbl.RECV_DATE_TIME ,mbl.RESULT_STATUS ,mbl.RESULT_DATE_TIME ,mbl.REGISTER_USER_ID ,mbl.MOD_TYPE ,CASE mbl.MOD_TYPE WHEN '01' THEN '운항정보정정' WHEN '02' THEN 'M-B/L 정정' WHEN '03' THEN 'M-B/L 추가' WHEN '04' THEN 'M-B/L 삭제' WHEN '05' THEN 'H-B/L 정정' WHEN '06' THEN 'H-B/L 추가' WHEN '07' THEN 'H-B/L 삭제' WHEN '99' THEN '컨테이너정정' END AS MOD_TYPE_NAME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = mbl.ENT_CODE AND USER_ID = mbl.REGISTER_USER_ID) AS REGISTER_USER_NAME ,mbl.REGISTER_DATE_TIME ,od.BOUND ,od.BOUND_TYPE FROM TB_EDI_MOD_MBL mbl INNER JOIN TB_ECM_OD od ON od.MBL_NO = mbl.MBL_NO AND od.BL_TYPE_MH = 'M' WHERE mbl.ENT_CODE = #{srchEntCode}
AND mbl.BOUND = #{srchBound}
AND od.BOUND_TYPE = CASE WHEN #{srchBoundType} IN('AO', 'SO') THEN 'EXP' ELSE 'IMP' END
AND mbl.MOD_TYPE = #{srchModType}
AND mbl.${srchNoType} IN (#{item})
AND mbl.${srchNoType} = #{srchNo}
AND mbl.REGISTER_DATE_TIME >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND mbl.REGISTER_DATE_TIME < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))

/* ManifestMapper.selectCorrectHouseList : 적하정정 House List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT mbl.MRN ,mbl.MSN ,mbl.MBL_NO ,mbl.MOD_SERIAL_NO ,mbl.MOD_REQ_DATE ,mbl.SEND_STATUS ,hbl.MOD_JOB_NO ,hbl.SEQ_NO_ID ,hbl.HSN ,hbl.HBL_NO ,hbl.OD_JOB_NO ,hbl.MOD_TYPE ,CASE hbl.MOD_TYPE WHEN '01' THEN '운항정보정정' WHEN '02' THEN 'M-B/L 정정' WHEN '03' THEN 'M-B/L 추가' WHEN '04' THEN 'M-B/L 삭제' WHEN '05' THEN 'H-B/L 정정' WHEN '06' THEN 'H-B/L 추가' WHEN '07' THEN 'H-B/L 삭제' WHEN '99' THEN '컨테이너정정' END AS MOD_TYPE_NAME ,hbl.MOD_REASON ,hbl.SINGLE_MOD_CODE ,hbl.SINGLE_MOD_REASON_CODE ,hbl.BEFORE_VALUE ,hbl.AFTER_VALUE ,hbl.REGISTER_USER_ID ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = mbl.ENT_CODE AND USER_ID = hbl.REGISTER_USER_ID) AS REGISTER_USER_NAME ,hbl.REGISTER_DATE_TIME ,od.BOUND ,od.BOUND_TYPE
,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND CODE = hbl.SINGLE_MOD_CODE AND GROUP_CODE = 'MOD_CODE') AS SINGLE_MOD_NAME ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND CODE = hbl.SINGLE_MOD_REASON_CODE AND GROUP_CODE = 'MOD_REASON_CODE') AS SINGLE_MOD_REASON_NAME
,od.BL_TYPE_IERT ,od.DEST_CODE ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND CODE = od.DEST_CODE AND GROUP_CODE = 'CITY_PORT') AS DEST_CODE_NAME ,od.DEST_COUNTRY ,od.PIECES ,od.UNIT_PIECES ,od.GWT ,od.COMMODITY_ITEM
,od.ASSIGNMENT_CODE ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND CODE = od.ASSIGNMENT_CODE AND GROUP_CODE = 'EDI_ASSIGNMENT_CODE') AS ASSIGNMENT_NAME ,od.SHIPPER_NAME ,od.SHIPPER_ADDRESS ,od.SHIPPER_BUSINESS_ID ,od.SHIPPER_COUNTRY_CODE ,od.SHIPPER_TEL ,od.SHIPPER_STATE_CODE
,od.CONSIGNEE_NAME ,od.CONSIGNEE_BUSINESS_ID ,od.CONSIGNEE_ADDRESS ,od.CONSIGNEE_COUNTRY_CODE ,od.CONSIGNEE_STATE_CODE
,mbl.SEND_DATE_TIME ,mbl.RESULT_DATE_TIME ,mbl.RECV_DATE_TIME
,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) AS CONSIGNEE_TEL
,od.CONSIGNEE_TEL
FROM TB_EDI_MOD_HBL hbl INNER JOIN TB_ECM_OD od ON od.OD_JOB_NO = hbl.OD_JOB_NO INNER JOIN TB_EDI_MOD_MBL mbl ON mbl.MOD_JOB_NO = hbl.MOD_JOB_NO WHERE mbl.ENT_CODE = #{srchEntCode}
AND mbl.BOUND = #{srchBound}
AND od.BOUND_TYPE = CASE #{srchBoundType} WHEN 'AO' THEN 'EXP' ELSE 'IMP' END
AND hbl.${srchNoType} IN (#{item})
AND hbl.${srchNoType} = #{srchNo}
AND hbl.MOD_JOB_NO = #{modJobNo}
AND hbl.SEQ_NO_ID = #{seqNoId}
AND hbl.MOD_TYPE = #{srchModType}
AND hbl.REGISTER_DATE_TIME >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND hbl.REGISTER_DATE_TIME < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND hbl.MOD_JOB_NO IN #{item}

/* ManifestMapper.selectCorrectContainerList : 적하정정 Container List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT con.CNTR_MOD_TYPE ,con.CNTR_NO ,con.CNTR_SEQ_NO_ID ,con.CNTR_CODE ,con.CNTR_EDI_CODE ,con.CNTR_SEAL_NO_1 AS CNTR_SEAL_NO1 ,con.CNTR_SEAL_NO_2 AS CNTR_SEAL_NO2 ,con.CNTR_SEAL_NO_3 AS CNTR_SEAL_NO3 ,con.PIECES ,con.UNIT_PIECES ,hbl.OD_JOB_NO ,con.CNTR_MOD_CODE ,con.BEFORE_VALUE ,con.AFTER_VALUE ,hbl.MOD_JOB_NO ,hbl.SEQ_NO_ID ,hbl.REGISTER_USER_ID ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = mbl.ENT_CODE AND USER_ID = hbl.REGISTER_USER_ID) AS REGISTER_USER_NAME ,hbl.REGISTER_DATE_TIME ,mbl.MOD_REQ_DATE ,hbl.MOD_TYPE ,(SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = mbl.ENT_CODE AND CODE = con.CNTR_MOD_CODE AND GROUP_CODE = 'CNTR_MOD_CODE') AS CNTR_MOD_NAME FROM TB_EDI_MOD_CONTAINER con INNER JOIN TB_EDI_MOD_HBL hbl ON hbl.MOD_JOB_NO = con.MOD_JOB_NO AND hbl.SEQ_NO_ID = con.SEQ_NO_ID INNER JOIN TB_EDI_MOD_MBL mbl ON mbl.MOD_JOB_NO = hbl.MOD_JOB_NO WHERE mbl.ENT_CODE = #{srchEntCode}
AND mbl.BOUND = #{srchBound}
AND ${srchNoType} = #{srchNo}
AND hbl.MOD_JOB_NO = #{modJobNo}
AND con.CNTR_MOD_TYPE IN #{item}
AND hbl.SEQ_NO_ID = ${seqNoId}
AND con.CNTR_SEQ_NO_ID = ${cntrSeqNoId}

/* ManifestMapper.getSerialNo : 적하정정  정정번호 추출 */
SELECT CONCAT(REPLICATE('0', 4 - LEN(num)), num) AS modSerialNo
FROM
(		
	SELECT ISNULL(MAX(mbl.MOD_SERIAL_NO),0) + 1 AS num
	FROM TB_EDI_MOD_MBL mbl
	INNER JOIN TB_ECM_OD od ON mbl.MBL_NO = od.MBL_NO
	WHERE mbl.MRN = #{mrn}
) A

/* ManifestMapper.selectPopupCorrectMasterList : 적하정정 팝업 Master List */
SELECT * FROM ( SELECT mbl.MOD_JOB_NO ,od.OD_JOB_NO ,od.BOUND ,od.BOUND_TYPE ,od.VENDER_ID_1 ,ROW_NUMBER() OVER(PARTITION BY mbl.MOD_JOB_NO ORDER BY mbl.MOD_JOB_NO) AS MOD_NUM ,mbl.ENT_CODE ,mbl.ENT_BUSINESS_CODE ,mbl.MRN ,mbl.MSN ,mbl.MBL_NO ,mbl.HBL_CNT ,mbl.MOD_SERIAL_NO ,mbl.MOD_REQ_DATE ,mbl.CUSTOMS_CODE ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = mbl.ENT_CODE AND CODE = mbl.CUSTOMS_CODE AND GROUP_CODE = 'EDI_CUSTOMS_CODE') AS CUSTOMS_NAME ,mbl.CUSTOMS_DPT_CODE ,mbl.SEND_STATUS ,mbl.SEND_DATE_TIME ,mbl.RECV_STATUS ,mbl.RECV_DATE_TIME ,mbl.RESULT_STATUS ,mbl.RESULT_DATE_TIME ,mbl.REGISTER_USER_ID ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = mbl.ENT_CODE AND USER_ID = mbl.REGISTER_USER_ID) AS REGISTER_USER_NAME ,mbl.REGISTER_DATE_TIME FROM TB_EDI_MOD_MBL mbl LEFT JOIN TB_EDI_MOD_HBL hbl ON mbl.MOD_JOB_NO = hbl.MOD_JOB_NO LEFT JOIN TB_ECM_OD od ON od.MBL_NO = mbl.MBL_NO AND BL_TYPE_MH = 'M' WHERE mbl.ENT_CODE = #{srchEntCode}
AND mbl.MOD_TYPE = #{srchModType}
AND mbl.BOUND = #{srchBound}
AND od.BOUND_TYPE = #{srchBoundType}
AND mbl.MBL_NO = #{srchNo}
AND hbl.HBL_NO = #{srchNo}
AND mbl.MOD_JOB_NO = #{srchNo}
AND mbl.MRN = #{srchNo}
AND mbl.${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND mbl.${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND mbl.REGISTER_DATE_TIME >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND mbl.REGISTER_DATE_TIME < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
) mbl WHERE MOD_NUM = 1

/* ManifestMapper.selectEmsOblCheck : 특송비엘생성전 체크 */
SELECT OBL_JOB_NO FROM TB_COM_OBL WHERE MBL_NO = #{MBL_NO} AND BL_TYPE_MH = 'M'
SELECT TOP 1 obl.OBL_JOB_NO ,obl.PIECES ,obl.GWT ,cus.CUSTOMER_NAME_ENG ,cus.EXRATE_TYPE ,CONCAT(ISNULL(cus.ADDRESS_ENG, ''), ISNULL(cus.ADDRESS_A_ENG, ''), ISNULL(cus.ADDRESS_B_ENG, '')) AS CUSTOMER_ADDRESS FROM TB_SMS_CUSTOMER cus LEFT JOIN TB_COM_OD od ON od.MBL_NO = #{MBL_NO} AND od.AR_ACCOUNT_CODE = cus.CUSTOMER_CODE AND od.BL_TYPE_MH = 'H' LEFT JOIN TB_COM_OBL obl ON obl.OBL_JOB_NO = od.OBL_JOB_NO WHERE cus.CUSTOMER_CODE = #{customerCode}

/* ManifestMapper.selectExchangeRateType */
	SELECT
		 bus.EXRATE_DECIMAL
		,bus.CURRENCY_CODE AS CURRENCY_CODE_LOC
		,(SELECT EXRATE_TYPE_AI FROM TB_SMS_ENT_BUS_FMS WHERE ENT_CODE = bus.ENT_CODE AND ENT_BUSINESS_CODE = bus.ENT_BUSINESS_CODE AND SOLUTION = 'EMS') AS EXRATE_TYPE
		,(SELECT ETC10 FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = bus.ENT_CODE AND CODE = #{ORIG_CODE} AND GROUP_CODE = 'CITY_PORT') AS CURRENCY_CODE
	FROM TB_SMS_ENT_BUSINESS bus
	WHERE bus.ENT_CODE = #{entCode}
	AND bus.ENT_BUSINESS_CODE = #{entBusinessCode}

