				,SEQ_NO_ID
				,HSN
				,HBL_NO
				,OD_JOB_NO
				,MOD_TYPE
				,MOD_REASON
				,SINGLE_MOD_CODE
				,SINGLE_MOD_REASON_CODE
				,BEFORE_VALUE
				,AFTER_VALUE
				,REGISTER_USER_ID
				,REGISTER_DATE_TIME
			)
			SELECT
				#{modJobNo}
				,(SELECT ISNULL(MAX(SEQ_NO_ID),0) + 1 FROM TB_EDI_MOD_HBL WHERE MOD_JOB_NO = #{modJobNo})
				,#{item.hsn}
				,#{item.hblNo}
				,od.OD_JOB_NO
				,CASE WHEN #{item.modType} = 'G' THEN '07'
					  WHEN #{item.modType} = 'F' THEN '06'
					  WHEN #{item.modType} = 'E' THEN '05'  END
				,#{item.modReason}
				,#{item.singleModCode}
				,#{item.singleModReasonCode}
				,#{item.beforeValue}
				,#{item.afterValue}
				,#{registerUserId}
				,DATEADD(HOUR, ${gmtTime}, GETDATE())
			FROM TB_ECM_OD od
			WHERE MBL_NO = #{item.mblNo}
				AND HBL_NO = #{item.hblNo} ;
						   
      		
			
				
