SET HBL_CNT = (SELECT COUNT(1) FROM TB_EDI_MOD_HBL WHERE MOD_JOB_NO = #{modJobNo})

,MOD_REQ_DATE = CONCAT(CONVERT(DATE, #{modReqDate}, ${dateFormat}), ' ', #{modReqTime}, ':00')

WHERE MOD_JOB_NO = #{modJobNo}

