AND cntr.CNTR_MOD_CODE IN (#{item.cntrModCode})

/* ManifestMapper.selectHblValidate : hbl유효성체크 */ WITH TMP AS( SELECT A.ENT_CODE, A.HBL_NO FROM (
SELECT #{entCode} AS ENT_CODE,#{item.mblNo} AS MBL_NO ,#{item.hblNo} AS HBL_NO
) A LEFT JOIN TB_ECM_OD OD ON OD.ENT_CODE = #{entCode} AND A.MBL_NO = OD.MBL_NO AND A.HBL_NO = OD.HBL_NO WHERE OD.OD_JOB_NO IS NULL ) SELECT COUNT(t.HBL_NO) AS NOT_BL_CNT , STUFF((SELECT ',' + HBL_NO FROM TMP WHERE ENT_CODE = t.ENT_CODE FOR XML PATH('')), 1, 1, '') FROM TMP t GROUP BY t.ENT_CODE

/* ManifestMapper.selectModHblValidate : 적하정정hbl유효성체크 */
WITH TMP AS( SELECT A.ENT_CODE, A.HBL_NO FROM (
SELECT #{entCode} AS ENT_CODE,#{modJobNo} AS MOD_JOB_NO ,#{item.hblNo} AS HBL_NO ,#{item.singleModCode} AS SINGLE_MOD_CODE
) A LEFT JOIN TB_EDI_MOD_HBL mod ON mod.MOD_JOB_NO = A.MOD_JOB_NO AND mod.HBL_NO = A.HBL_NO AND mod.SINGLE_MOD_CODE = A.SINGLE_MOD_CODE WHERE mod.MOD_JOB_NO IS NULL ) SELECT COUNT(t.HBL_NO) AS NOT_BL_CNT , STUFF((SELECT ',\n' + HBL_NO FROM TMP WHERE ENT_CODE = t.ENT_CODE FOR XML PATH('')), 1, 0, '') AS NOT_HBL_LIST FROM TMP t GROUP BY t.ENT_CODE

