/* ManifestMapper.getSeparationList : 개인통관오류건 리스트 조회 */ SELECT od.OD_JOB_NO ,od.HBL_NO ,CASE WHEN od.DOCUMENT_YN = 'Y' THEN 'Y' ELSE 'N' END AS DOCUMENT_YN
,ad.SIMPLE_DOC_NO
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON od.OD_JOB_NO = ad.OD_JOB_NO WHERE 1=1 AND od.BL_TYPE_MH = 'H'
AND od.MASTER_OD_JOB_NO = #{masterOdJobNo}
AND ad.SIMPLE_DOC_NO = #{simpleDocNo}
AND ad.SIMPLE_DOC_NO IS NULL
AND od.CD_TYPE = 'Y' AND ((ad.SIMPLE_EDI_STATUS = 'ERROR' AND (ISNULL(ad.SIMPLE_ERROR_DESC,'') != '')) OR (ad.CUSTOMS_ID_VERIFY IN ('N' ,'E')))

/* ManifestMapper.customsErrSeparation : 개인통관오류건 제출번호 분리 */
UPDATE ad
SET
	ad.SIMPLE_DOC_NO = #{newSimpleDocNo}
	
FROM TB_ECM_OD od
	INNER JOIN TB_ECM_OD_ADDITIONAL ad
	ON od.OD_JOB_NO = ad.OD_JOB_NO
	
WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo}
	


AND ad.SIMPLE_DOC_NO = #{simpleDocNo}


AND ad.SIMPLE_DOC_NO IS NULL




AND (
	(
		od.BL_TYPE_MH = 'H'
		AND CASE WHEN od.DOCUMENT_YN = 'Y' THEN 'Y' ELSE 'N' END = #{documentYn}
		AND od.CD_TYPE = 'Y'
		AND ((ad.SIMPLE_EDI_STATUS = 'ERROR' AND ISNULL(ad.SIMPLE_ERROR_DESC,'') != '') OR ad.CUSTOMS_ID_VERIFY IN ('N', 'E'))
	)
	
	OR od.BL_TYPE_MH = 'M'
	
)


		
SELECT @@ROWCOUNT AS COUNT

