/* ManifestMapper.updateSimpleDocNoList  */
UPDATE TB_ECM_OD_ADDITIONAL
	SET SIMPLE_DOC_NO = #{newSimpleDocNo}
	WHERE OD_JOB_NO IN (
						SELECT OD_JOB_NO 
							FROM 
							(
							SELECT	
									ROW_NUMBER() OVER(ORDER BY od.HSN) AS ROWNUM
									,od.OD_JOB_NO
									,od.HSN
									,od.HBL_NO 
							  FROM
							  		TB_ECM_OD od
							  		LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON od.OD_JOB_NO = ad.OD_JOB_NO
							  		WHERE od.ENT_CODE = #{entCode}
							  		AND od.BL_TYPE_MH = 'H'
							  		AND od.MASTER_OD_JOB_NO  = #{masterOdJobNo}
							  		AND ad.SIMPLE_DOC_NO = #{simpleDocNo}
							 ) A 
							 WHERE ROWNUM > 5000
						)

