/* ManifestMapper.selectConsigneeMatchingInfo : 수하인정보 매칭처리할 재사용 List 조회 */ SELECT TOP 1
dbo.Cryptography(od.OD_JOB_NO, od.CUSTOMS_ID_ENC, 1) AS CUSTOMS_ID,
od.CUSTOMS_ID,
MRN, MSN, HSN FROM TB_ECM_OD od LEFT JOIN TB_CD_B_INFO info ON od.HBL_NO = info.HBL_NO WHERE od.CONSOL_YN = 'Y' AND info.CONSENT = 'Y' AND ISNULL(od.CUSTOMS_ID,'') != '' AND TRIM(od.CONSIGNEE_NAME) = #{CONSIGNEE_NAME}
AND RIGHT(dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1),8) = #{CONSIGNEE_TEL}
AND RIGHT(od.CONSIGNEE_TEL,8) = #{CONSIGNEE_TEL}
AND od.OD_JOB_NO != #{OD_JOB_NO} AND od.AR_DATE >= CONVERT(DATE, #{srchStartDate}, 23) AND od.AR_DATE <= CONVERT(DATE, #{srchEndDate}, 23) ORDER BY od.AR_DATE DESC

