AND tb1.HBL_NO IN(#{item})
FOR XML PATH('') ), 1, 1, '') AS HBL_NO_LIST , COUNT(od.HBL_NO) AS HBL_NO_CNT , MAX(od.BOUND) AS BOUND , MAX(od.BOUND_TYPE) AS BOUND_TYPE , MAX(od.VESSEL_FLIGHT) AS VESSEL_FLIGHT FROM TB_ECM_OD od INNER JOIN TB_UPS_BASIC ups ON ups.BASIC_TYPE = 'F' AND ups.HBL_NO = SUBSTRING(od.REMARKS, 0, 7) WHERE od.MBL_NO = #{mblNo} AND od.BL_TYPE_MH = 'H'
AND od.HBL_NO IN(#{item})
GROUP BY ups.HBL_NO, ups.ETC1

