/* ManifestMapper.updateCustomsManifestCancel : 목록취하신고상태 */
	UPDATE ad SET
		   
		   
		   ad.SIMPLE_DROP_EDI_STATUS = 'ERROR'
		   
		   
		   ad.SIMPLE_DROP_EDI_STATUS = 'READY'
		   
		   
		  ,ad.LAST_POD_STATUS = CASE WHEN ISNULL(ad.LAST_POD_STATUS, '') = 'ECM134' THEN #{podStatus} ELSE
		 						CASE WHEN ISNULL(ad.LAST_POD_STATUS, '') < #{podStatus} THEN #{podStatus} ELSE ad.LAST_POD_STATUS END END
		  ,ad.SIMPLE_ERROR_SEND_YN = 'N'
		  
		  ,ad.SIMPLE_DROP_TIME = #{simpleDocDate}
		  ,ad.SIMPLE_DROP_CODE = #{simpleDropCode}
		  ,ad.SIMPLE_DROP_ETC = #{simpleDropEtc}
		  ,ad.SIMPLE_DROP_CNT = #{simpleDropCnt}
		  
	FROM TB_ECM_OD od
		 INNER JOIN TB_ECM_OD_ADDITIONAL ad
		 			ON ad.OD_JOB_NO = od.OD_JOB_NO
	
	
	WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo}
	
	
	WHERE od.OD_JOB_NO IN(#{item})
	
	
	AND od.BL_TYPE_MH = 'H'
	AND od.BL_TYPE_IERT NOT IN('T', 'R')
	AND od.CD_TYPE = 'Y'
	
	
	
	AND ad.SIMPLE_DROP_EDI_STATUS = 'READY'
	
	
	AND (ad.SIMPLE_DROP_EDI_STATUS IS NULL OR ad.SIMPLE_DROP_EDI_STATUS = 'ERROR')
	
	
	
	
	AND ad.SIMPLE_DOC_NO = #{simpleDocNo}
	
	
	AND od.ORIG_CODE = #{origCode}
	
	
	AND ad.SIMPLE_DOC_NO != ''
	AND ad.SIMPLE_DOC_NO IS NOT NULL

/* ManifestMapper.updateSimpleCancelErrorDescNull : 목록취하신고시 오류내역제거 */
	UPDATE ad SET
		   ad.SIMPLE_DROP_ERROR_DESC = NULL
	FROM TB_ECM_OD od
		 INNER JOIN TB_ECM_OD_ADDITIONAL ad
		 			ON ad.OD_JOB_NO = od.OD_JOB_NO
	
	
	WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo}
	
	
	WHERE od.OD_JOB_NO IN(#{item})
	
	
	AND od.BL_TYPE_MH = 'H'
	
	
	AND ad.SIMPLE_DOC_NO = #{simpleDocNo}
	
	
	AND od.ORIG_CODE = #{origCode}
	
	
	AND ad.SIMPLE_DOC_NO != ''
	AND ad.SIMPLE_DOC_NO IS NOT NULL

/* ManifestMapper.updateResetSendCustomsManifestInfo : 목록신고 개별초기화 */ UPDATE ad SET ad.SIMPLE_EDI_STATUS = NULL ,ad.SIMPLE_DOC_DATE = NULL ,ad.SIMPLE_DOC_TIME = NULL ,ad.SIMPLE_RESPONSE_DATE = NULL ,ad.SIMPLE_REPORT_DATE = NULL ,ad.LAST_POD_STATUS = CASE WHEN od.BL_TYPE_MH = 'M' THEN #{lastPodStatusMaster} ELSE #{lastPodStatus} END
,ad.SIMPLE_RESULT_DATE = NULL ,ad.SIMPLE_AUTH_NAME = NULL ,ad.SIMPLE_STATEMENT_YN = 'N' ,ad.SIMPLE_STATEMENT_REASON = NULL ,ad.SE_INSPECTION_YN = 'N' ,ad.SE_INSPECTION_CODE = NULL ,ad.DROP_CODE = NULL ,ad.DROP_YN = 'N' ,ad.CLEARANCE_RECEIPT_DATE = NULL
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO WHERE od.OD_JOB_NO = #{odJobNo}
AND od.CD_TYPE IN('Y', 'N')
AND od.CD_TYPE IN('E', 'N')

