mapper.select:
/* ManifestMapper.selectInsertEms : 적하목록 수입 특송생성데이터 조회 */ SELECT MASTER_OD_JOB_NO ,CUSTOMER_CODE ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE CUSTOMER_CODE = ems.CUSTOMER_CODE) AS UPPER_CUS_NAME ,MAX(AR_DATE) AS AR_DATE ,SUM(PIECES) AS HOUSE_PIECES ,SUM(GWT) AS HOUSE_CWT ,SUM(GWT) AS HOUSE_GWT ,COUNT(OD_JOB_NO) AS HOUSE_COUNT ,COUNT(CASE WHEN ISNULL(CD_TYPE,'') = 'Y' THEN 1 END) AS CD_TYPE1 ,COUNT(CASE WHEN ISNULL(CD_TYPE,'') = 'B' THEN 1 END) AS CD_TYPE2 ,COUNT(CASE WHEN ISNULL(CD_TYPE,'') = 'N' THEN 1 END) AS CD_TYPE3 ,COUNT(CASE WHEN ISNULL(CD_TYPE,'') = 'NA' THEN 1 END) AS CD_TYPE4 ,COUNT(CASE WHEN ISNULL(INSPECTION_YN,'') = 'Y' THEN 1 END) AS INSPECTION_YN ,COUNT(CASE WHEN ISNULL(SE_INSPECTION_YN,'') = 'Y' THEN 1 END) AS SE_INSPECTION_YN ,COUNT(CASE WHEN ISNULL(DROP_YN,'') = 'Y' THEN 1 END) AS DROP_YN ,COUNT(CASE WHEN ISNULL(XRAY_YN,'') = 'Y' THEN 1 END) AS XRAY_YN ,COUNT(CASE WHEN ISNULL(CRIME_SELECTION_YN,'') = 'Y' THEN 1 END) AS CRIME_SELECTION_YN ,COUNT(CASE WHEN ISNULL(GE_INSPECTION_YN,'') = 'Y' THEN 1 END) AS GE_INSPECTION_YN FROM ( SELECT od.MASTER_OD_JOB_NO ,od.ENT_CODE ,od.OD_JOB_NO ,CASE WHEN od.CUST_CODE_LV7 IS NOT NULL THEN od.CUST_CODE_LV7 WHEN od.CUST_CODE_LV6 IS NOT NULL THEN od.CUST_CODE_LV6 WHEN od.CUST_CODE_LV5 IS NOT NULL THEN od.CUST_CODE_LV5 WHEN od.CUST_CODE_LV4 IS NOT NULL THEN od.CUST_CODE_LV4 WHEN od.CUST_CODE_LV3 IS NOT NULL THEN od.CUST_CODE_LV3 WHEN od.CUST_CODE_LV2 IS NOT NULL THEN od.CUST_CODE_LV2 ELSE od.CUST_CODE_LV1 END AS CUSTOMER_CODE ,master.AR_DATE ,od.PIECES ,od.GWT ,od.CBM ,od.CD_TYPE ,od.INSPECTION_YN ,od.GE_INSPECTION_YN ,ad.SE_INSPECTION_YN ,ad.DROP_YN ,ad.XRAY_YN ,ad.CRIME_SELECTION_YN FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON od.OD_JOB_NO = ad.OD_JOB_NO LEFT JOIN TB_ECM_OD master ON master.OD_JOB_NO = od.MASTER_OD_JOB_NO WHERE od.ENT_CODE = #{srchEntCode} AND od.BL_TYPE_MH = 'H' AND od.FINISH_YN = 'Y' AND od.MASTER_OD_JOB_NO = #{masterOdJobNo}
AND od.BOUND = 'AIR' AND od.BOUND = 'SEA'
AND od.BOUND_TYPE = 'EXP' AND od.BOUND_TYPE = 'IMP'
) AS ems GROUP BY MASTER_OD_JOB_NO, CUSTOMER_CODE

/* ManifestMapper.selectEcmYnCheck : DKX 제출번호 분리 체크 */ SELECT CASE WHEN COUNT(DISTINCT ISNULL(ECM_YN, 'N')) = 2 THEN 'Y' ELSE 'N' END AS ECM_YN_CHK ,MAX(ISNULL(ECM_YN,'N')) AS ECM_YN FROM TB_ECM_OD od WHERE MASTER_OD_JOB_NO = #{srchMasterOdJobNo} AND BL_TYPE_MH = 'H'
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
